"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["38797"],{15424(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.fonte_valores_obrigatoria","status":422,"titulo":"Fato categ\xf3rico precisa declarar a fonte dos seus valores"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.fonte_valores_obrigatoria","requisitos":["UNI-REQ-0143","UNI-REQ-0159"],"oQueAconteceu":["O fato categ\xf3rico \xe9 escolhido numa lista, e a fonte dos valores diz de onde v\xeam as op\xe7\xf5es (UNI-REQ-0143). O cadastro de um fato declarado (`POST /api/configuracao/admin/fatos-candidato`) ou a altera\xe7\xe3o da defini\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) de um fato declarado trouxe o `dominio` `CATEGORICO` com a `fonteValores` ausente, vazia ou com um valor que n\xe3o pertence ao vocabul\xe1rio. Para a fonte, as duas situa\xe7\xf5es recebem este mesmo c\xf3digo de erro.","A recusa vem na lista `errors` da resposta, com `field` igual a `fonteValores`. Ela s\xf3 \xe9 dada quando o dom\xednio \xe9 v\xe1lido. Nada \xe9 gravado. No fato de sistema, que s\xf3 aceita mudar o nome, a descri\xe7\xe3o, a forma de exibi\xe7\xe3o e a prote\xe7\xe3o de dados, uma fonte fora do vocabul\xe1rio tamb\xe9m recebe esta recusa, antes da recusa de [defini\xe7\xe3o do fato de sistema travada](/erros/uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada)."],"comoResolver":["Informe uma destas fontes, escrita exatamente assim, em mai\xfasculas: `GLOBAL`, `PROCESSO`, `MODALIDADE`, `MUNICIPIOS_BONUS`, `GEO_UF`, `GEO_MUNICIPIO` ou `TIPOS_DEFICIENCIA`. Com `GLOBAL`, as op\xe7\xf5es s\xe3o cadastradas no pr\xf3prio fato (`POST /api/configuracao/admin/fatos-candidato/{id}/valores`); nas demais, v\xeam do processo ou de outro cadastro, e o fato n\xe3o guarda valores. O fato derivado por regra categ\xf3rico usa a fonte `GLOBAL`, inferida, e o resumo de grupo herda a do fato de membro."],"ondeAparece":["Cadastro de um fato declarado do cat\xe1logo","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);